def generate_primes(n: int) -> list[int]:
    """Return a list of all primes lower than n."""
    if n <= 2:
        return []
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    for current in range(2, int(n**0.5) + 1):
        if sieve[current]:
            for multiple in range(current * current, n, current):
                sieve[multiple] = False
    return [num for num, is_prime in enumerate(sieve) if is_prime]

def check_key(dictionary: dict, key: str) -> bool:
    """
    Recursively checks if a key exists in a nested dictionary structure.

    Args:
        dictionary: The dictionary (possibly nested) to search in.
        key: The key to search for.

    Returns:
        True if the key is found in the dictionary or any nested dictionaries, False otherwise.
    """
    if key in dictionary:
        return True

    for value in dictionary.values():
        if isinstance(value, dict):
            if check_key(value, key):
                return True
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    if check_key(item, key):
                        return True

    return False

def find_missing_positive(nums: list[int]) -> int:
    """Return the smallest positive integer not present in the list.

    Args:
        nums: A list of integers.

    Returns:
        The smallest positive integer missing from the list. If all integers are non-positive, return 1.
    """
    positives = {num for num in nums if num > 0}
    if not positives:
        return 1

    max_pos = max(positives)
    for i in range(1, max_pos + 2):
        if i not in positives:
            return i

    return max_pos + 1

def max_in_list(lst):
