    for num in lst[1:]:
        if num > max_num:
            max_num = num
    return max_num

def max_subarray_sum(numbers, k):
    current_sum = sum(numbers[:k])
    max_sum = current_sum
    for i in range(k, len(numbers)):
        current_sum = current_sum - numbers[i - k] + numbers[i]
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum

def perms(s):
    # Base case: single character
    if len(s) == 1:
        return [s]
    result = []
    for i, char in enumerate(s):
        # Generate permutations of remaining characters
        for p in perms(s[:i] + s[i+1:]):
            result.append(char + p)
    return result

