def decimal_to_binary(n: int) -> str:
    """
    Recursively converts a non-negative decimal integer to its binary string representation.

    Args:
        n: A non-negative integer to be converted.

    Returns:
        The binary representation of n as a string.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    def helper(num: int) -> str:
        if num == 0:
            return '0'
        elif num == 1:
            return '1'
        else:
            return helper(num // 2) + str(num % 2)

    return helper(n)

def convert_temperature(temp, conversion_type):
    if conversion_type == 'C_to_F':
        return (temp * 9/5) + 32
    elif conversion_type == 'F_to_C':
        return (temp - 32) * 5/9
    else:
        raise ValueError("Invalid conversion type")

def get_valid_number(prompt):
    while True:
        user_input = input(prompt)
        try:
            return float(user_input)
        except ValueError:
            print("Please enter a valid number.")

def main():
    print("Temperature Conversion Tool")
    print("1. Celsius to Fahrenheit")
    print("2. Fahrenheit to Celsius")
    choice = get_valid_number("Enter your choice (1 or 2): ")
    if choice == 1:
        temp = get_valid_number("Enter temperature in Celsius: ")
        result = convert_temperature(temp, 'C_to_F')
        print(f"{temp}°C is equal to {result}°F")
    elif choice == 2:
        temp = get_valid_number("Enter temperature in Fahrenheit: ")
        result = convert_temperature(temp, 'F_to_C')
        print(f"{temp}°F is equal to {result}°C")
    else:
        print("Invalid choice.")

if __name__ == "__main__":
    main()

