from typing import Dict, Any

def flatten_dict(nested_dict: Dict[str, Any]) -> Dict[str, Any]:
    """
    Flattens a nested dictionary into a single-level dictionary.

    Args:
        nested_dict: A dictionary containing nested structures.

    Returns:
        A new dictionary with keys from nested_dict flattened using dot notation.

    Raises:
        TypeError: If input is not a dictionary.
    """
    if not isinstance(nested_dict, dict):
        raise TypeError("Input must be a dictionary")

    flattened: Dict[str, Any] = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            # Recursively flatten nested dict and merge with parent key
            sub_dict = flatten_dict(value)
            for subkey, subvalue in sub_dict.items():
                flattened[f"{key}.{subkey}"] = subvalue
        else:
            flattened[key] = value
    return flattened

from typing import List, Dict

def transform_json_to_dict(data: List[Dict[str, str]]) -> Dict[str, str]:
    """Transform a list of JSON-like dictionaries into a dictionary mapping names to jobs."""
    name_job_map: Dict[str, str] = {}
    for entry in data:
        name_job_map[entry['name']] = entry['job']
    return name_job_map

def is_valid(s: str) -> bool:
    allowed_punctuation = {',', '.', '!', '?'}
    has_lowercase = False
    for char in s:
        if not (char.islower() or char in allowed_punctuation):
            return False
        if char.islower():
            has_lowercase = True
    return has_lowercase

