def is_palindrome(s):
    filtered = [c.lower() for c in s if c.isalpha()]
    return filtered == filtered[::-1]

import math

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(math.sqrt(n)) + 1
    for i in range(3, max_divisor, 2):
        if n % i == 0:
            return False
    return True
